const COMMAND_TYPE_SET: ReadonlySet<string> = new Set<string>(COMMAND_TYPES);

export function isCommandType(value: string): value is CommandType {
  return COMMAND_TYPE_SET.has(value);
}

/** The strings-table key the UI shows for a rejection. */
export function rejectStringKey(reason: RejectReason): string {
  return `reject.${reason}`;
}
